age = int(input("Сколько тебе лет? "))
if age >= 18:
    print("Доступ открыт")
else:
    print("Доступ закрыт")

temperature = int(input("Какая температура на улице? "))
if temperature < 0:
    print("Мороз")
else:
    print("Ноль градусов или теплее")

first = int(input("Первое число: "))
second = int(input("Второе число: "))

if first >= second:
    print(first)
else:
    print(second)

tickets = int(input("Сколько билетов купили? "))

if tickets <= 0:
    print("Количество билетов должно быть больше нуля.")
else:
    print("К оплате:", tickets * 1500)

names = ["Алия", "Данияр", "Мадина"]
for name in names:
    print(name)

numbers = [2, 4, 6]
for number in numbers:
    print(number * 2)

prices = [900, 1500, 2200, 1200]
for price in prices:
    if price >= 1500:
        print(price)

prices = [1500, 900, 2200, 1500]
count = 0

for price in prices:
    if price == 1500:
        count = count + 1

print(count)

def square(number):
    return number * number

print(square(5))

def ticket_total(price, count):
    return price * count

print(ticket_total(1500, 3))
